node --env-file=../.env -e '
const { Client } = require("pg")
const url = process.env.ADMIN_DATABASE_URL
const c = new Client({ connectionString: url })
const q = async (t) => (await c.query(t)).rows
;(async () => {
  await c.connect()
  await c.query("begin read only")
  const out = {}
  out.server = (await q("show server_version"))[0].server_version
  out.role = (await q("select current_user u"))[0].u
  out.controls = await q("select scope, suspended, version, changed_at from ascend_automation_controls order by scope")
  out.definitions = await q("select action_type, enabled, requires_approval, max_concurrency, interval_seconds, market_scope, policy_version from ascend_automation_definitions order by action_type")
  out.executions = await q("select status, count(*)::int n from ascend_executions group by status")
  out.events = (await q("select count(*)::int n from ascend_execution_events"))[0].n
  out.identities = await q("select kind, active, cardinality(allowed_actions) actions, count(*)::int n from ascend_service_identities group by 1,2,3")
  out.workers = await q("select status, count(*)::int n from ascend_workers group by status")
  out.controlEvents = (await q("select count(*)::int n from ascend_control_events"))[0].n
  out.reviewJobs = await q("select status, count(*)::int n from ascend_review_jobs group by status")
  for (const t of ["partner_applications","expansion_partners","expansion_opportunities","expansion_commission_ledger","expansion_payouts","partner_agreement_acceptances","admin_users"]) {
    try { out["count_" + t] = (await q(`select count(*)::int n from ${t}`))[0].n } catch (e) { out["count_" + t] = "error:" + e.code }
  }
  try { out.migrations = (await q("select count(*)::int n, max(created_at) last from drizzle.__drizzle_migrations"))[0] } catch (e) { out.migrations = "error:" + e.code }
  try { out.stmtTimeout = (await q("show statement_timeout"))[0].statement_timeout } catch {}
  await c.query("rollback"); await c.end()
  console.log(JSON.stringify(out, null, 1))
})().catch((e) => { console.error("query failed:", e.code || e.name); process.exit(1) })
'

